import {discoverWorksite} from './worksite-layout.mjs';
// Functional scene grammars. Values are explicit village-demo capacities, not asset metadata.
export const DOMESTIC_SCENES={
 market:{label:'Market',name:'Market square',presets:{stalls:'Market stalls',court:'Trading court',fair:'Village fair'},purpose:'Arrange sheltered stalls, goods and gathering space.',uses:['vendors','visitors'],inputs:[],outputs:[],capabilities:{}},
 home:{label:'Home',name:'Home courtyard',presets:{courtyard:'Shared courtyard',lane:'Household lane',garden:'Garden homes'},purpose:'Shelter households and organize cooking, water and rest.',uses:['residents','visitors'],inputs:['food','fuel','water'],outputs:['household life'],capabilities:{housing:6}},
 garden:{label:'Garden',name:'Productive garden',presets:{kitchen:'Kitchen beds',surplus:'Market surplus',seeds:'Seed garden'},purpose:'Feed households and produce a harvest surplus.',uses:['gardeners'],inputs:['labor','water','seed'],outputs:['rawFood'],capabilities:{garden:12}},
 woodland:{label:'Woodland',name:'Working woodland',presets:{coppice:'Coppice fuel',timber:'Timber clearing',reserve:'Forest reserve'},purpose:'Regrow and prepare wood for household and workshop fuel.',uses:['woodcutters','haulers'],inputs:['labor','standing timber'],outputs:['fuel'],capabilities:{woodland:4}},
 pottery:{label:'Pottery',name:'Clay workshop',presets:{kiln:'Firing yard',clay:'Clay preparation',vessels:'Vessel workshop'},purpose:'Process a finite clay reserve with woodland fuel into vessels.',uses:['potters'],inputs:['clay','fuel','labor'],outputs:['vessels'],capabilities:{pottery:2}},
 preservation:{label:'Preserve',name:'Harvest store',presets:{roots:'Root storage',drying:'Drying yard',pantry:'Shared pantry'},purpose:'Preserve garden surplus using vessels and storage.',uses:['preservers','haulers'],inputs:['rawFood','vessels','labor'],outputs:['food'],capabilities:{preservation:2}},
 gathering:{label:'Gather',name:'Shared meal court',presets:{meal:'Shared meal',market:'Market table',commons:'Village commons'},purpose:'Bring households together for food and shared work.',uses:['residents','visitors'],inputs:['food'],outputs:['communal meal'],capabilities:{gathering:6}},
 animals:{label:'Animals',name:'Companion yard',presets:{care:'Care yard',rest:'Quiet refuge',garden:'Garden companions'},purpose:'Provide companions with feeding, water and sheltered rest.',uses:['carers','cats','dogs'],inputs:['food','water','care'],outputs:['companionship'],capabilities:{}}
};
const item=(asset,x,z,extra={})=>({asset,x,z,y:0,angle:0,purpose:'working equipment',...extra});
function house(){return [item('GF-191',0,-3,{purpose:'household shelter'}),item('roof',0,-3,{y:2.62,size:[5.8,.20,4.9],purpose:'procedural weather cover'}),item('GF-017',-4.8,2,{purpose:'shaded work and rest'}),item('GF-014',4,1,{purpose:'household water'}),item('WW-003',4,-1,{purpose:'dry fuel'}),item('BA-0018',-3,3,{purpose:'rest'}),item('BA-0088',1.5,2.8,{purpose:'resident'})];}
function beds(){const a=[item('soil',-2.725,-2.28,{y:.02,size:[3.6,.04,4.3],purpose:'cultivated planting bed'}),item('soil',2.725,-2.28,{y:.02,size:[3.6,.04,4.3],purpose:'cultivated planting bed'}),item('GF-014',5,-3,{purpose:'watering'}),item('GF-030',-4,3,{purpose:'sort harvest'}),item('GF-081',4,1.8,{purpose:'wash harvest'}),item('GF-025',4,4,{purpose:'harvest storage'}),item('GF-008',1.3,4.2,{purpose:'garden tending'}),item('GF-007',1,4.2,{purpose:'tending tool'})];for(let row=0;row<5;row++)for(let col=0;col<8;col++)a.push(item('GF-004',(col<4?-4+col*.85:1.45+(col-4)*.85),-4+row*.86,{purpose:'harvestable crop'}));return a;}
function fuel(){return [item('GF-133',3,-3,{purpose:'seasoned fuel storage'}),item('WW-051',1.5,1,{purpose:'fuel processing'}),...Array.from({length:6},(_,i)=>item('WW-003',2+i%3*1.35,-.8+Math.floor(i/3)*1.1,{purpose:'fuel stock'})),...Array.from({length:12},(_,i)=>item('WW-001',-5+i%3*1.7,-4+Math.floor(i/3)*1.7,{purpose:'coppice regrowth'}))];}
function pottery(){return [item('GF-017',-2.5,1,{purpose:'shade for clay shaping'}),item('RF-001',-4,-3,{purpose:'finite clay source'}),item('RF-041',0,-3,{purpose:'levigate clay'}),item('RF-042',-2,1,{purpose:'throw vessels'}),item('RF-043',1.5,1,{purpose:'vessel work in progress'}),item('RF-044',4,-3,{purpose:'fire vessels'}),item('WW-003',4,0,{purpose:'kiln fuel'}),item('BA-0024',3,3,{purpose:'finished vessels'}),item('BA-0083',-3,3,{purpose:'potter'}),item('GF-014',-5,0,{purpose:'clay processing water'})];}
function stores(){return [item('GF-017',0,-3,{purpose:'weather protection'}),item('GF-027',-3,-2,{purpose:'dry crop surplus'}),item('GF-027',-4.6,-2,{purpose:'dry crop surplus'}),item('GF-026',3,-2,{purpose:'root storage'}),item('GF-023',3,1,{purpose:'seed saving'}),item('GF-025',-3,2,{purpose:'receiving harvest'}),item('GF-014',1.5,1,{purpose:'washing water'}),item('BA-0088',1.5,3,{purpose:'preservation worker'})];}
function gathering(){return [item('GF-192',0,-3,{purpose:'shared cooking'}),item('GF-193',0,-3,{y:.29,purpose:'cooking vessel'}),item('GF-193.prepared-meal',0,-3,{y:.58,purpose:'meal contents'}),item('GF-014',-3,-3,{purpose:'cooking water'}),item('GF-029',3,-3,{purpose:'grind meal'}),item('BA-0012',-2,1,{purpose:'serve meal'}),item('BA-0043',-2,1,{y:.56,purpose:'served flatbread'}),...[-1,1].flatMap(side=>[item('GF-194',side*3,1,{angle:side*Math.PI/2,purpose:'shared seating'}),item('BA-0088',side*3,3,{purpose:'meal participant'})])];}
function animals(){return [item('GF-017',0,-3,{purpose:'animal shade'}),item('GF-196',-1,-2,{purpose:'companion rest'}),item('GF-171',-1.8,0,{purpose:'household cat'}),item('UP-007',2,0,{purpose:'household dog'}),item('GF-195',-1.5,2,{purpose:'food and water'}),item('GF-014',-3,1,{purpose:'water supply'}),item('BA-0088',2,3,{purpose:'animal care'})];}
function market(){return [item('GF-017',0,-2,{purpose:'sheltered stall'}),item('BA-0012',-2,1,{purpose:'trading table'}),item('GF-025',-3,1,{purpose:'produce basket'}),item('GF-023',3,1,{purpose:'seed goods'}),item('BA-0088',0,-.5,{purpose:'vendor'})];}
const factories={market,home:house,garden:beds,woodland:fuel,pottery,preservation:stores,gathering,animals};
function sceneItems(type,preset){const a=factories[type]();if(type==='home'&&preset==='garden')for(let i=0;i<12;i++)a.push(item('GF-004',-5+(i%4)*.8,4.2+Math.floor(i/4)*.6,{purpose:'household kitchen crop'}));if(type==='garden'&&preset==='seeds')a.push(item('GF-023',-5,5.5,{purpose:'saved seed storage'}));if(type==='woodland'&&preset==='timber')for(let i=0;i<5;i++)a.push(item('WW-003',-5+i%3*1.4,3+Math.floor(i/3)*1.2,{purpose:'prepared wood bundles'}));if(type==='pottery'&&preset==='clay')a.push(item('RF-041',-4.5,4.8,{purpose:'extra clay preparation'}));if(type==='pottery'&&preset==='vessels')a.push(item('BA-0024',4,4.8,{purpose:'finished vessel storage'}));if(type==='preservation'&&preset==='drying')for(let i=0;i<3;i++)a.push(item('GF-027',[-4,-2,3][i],4.5,{purpose:'expanded drying capacity'}));if(type==='preservation'&&preset==='pantry')a.push(item('GF-023',4.5,3,{purpose:'shared seed reserve'}));if(type==='gathering'&&preset==='market')for(const x of [-4,4])a.push(item('BA-0012',x,4.5,{purpose:'exchange surplus'}));if(type==='gathering'&&preset==='commons')for(const x of [-4,-2,3])a.push(item('GF-194',x,5,{purpose:'public seating'}));if(type==='animals'&&preset==='rest')a.push(item('GF-196',1.2,-2,{purpose:'additional sheltered rest'}));if(type==='animals'&&preset==='garden')for(let i=0;i<6;i++)a.push(item('GF-004',[-4,-3,-2,2,3,4][i],4.8,{purpose:'garden margin'}));return a;}
export function domesticRequirements(type,preset,seed=41){const count=type==='market'?(preset==='fair'?5:preset==='court'?3:2):type==='home'?(preset==='lane'?5:4):type==='garden'?(preset==='surplus'?5:3):type==='woodland'?(preset==='reserve'?1:2):1;return Array.from({length:count},(_,i)=>({role:type,w:14,d:14,radius:10,...discoverWorksite(sceneItems(type,preset),{seed,type,preset,index:i}),purpose:DOMESTIC_SCENES[type].purpose,index:i}));}
export function domesticRecipe(type,preset,seed){const scene=DOMESTIC_SCENES[type];if(!scene||!scene.presets[preset])throw Error('Unknown scene preset');return {generator:'domestic-composer',version:1,type,preset,seed,requirements:domesticRequirements(type,preset,seed),landscape:{height:0,vegetation:type==='woodland'?3:2,props:0,seed:seed^173},tiles:[{id:type,type,cell:0,rotation:0,seed}]};}
export function completeDomesticPaths(assembly){for(const p of assembly.plans)for(const o of p.placements){if(!o.internalPaths)continue;for(const [index,points] of o.internalPaths.entries())p.paths.push({kind:'courtyard',width:o.internalPathWidths?.[index]||1.4,to:o.id,points:points.map(v=>({x:o.x+v.x*Math.cos(o.angle)+v.z*Math.sin(o.angle),z:o.z-v.x*Math.sin(o.angle)+v.z*Math.cos(o.angle)}))});}return assembly;}

export const DOMESTIC_AFFINITIES={home:{garden:3,gathering:3,animals:1},garden:{home:3,preservation:4},woodland:{pottery:4,home:1},pottery:{woodland:4,preservation:3},preservation:{garden:4,gathering:2},gathering:{home:4,preservation:2},animals:{home:3,garden:1}};
export function describeDomestic(type,preset,groups){const scene=DOMESTIC_SCENES[type];return `${scene.presets[preset]} arranges ${groups} working ${groups===1?'area':'areas'} for ${scene.uses.join(' and ')}. Its purpose is to ${scene.purpose[0].toLowerCase()+scene.purpose.slice(1)} It receives ${scene.inputs.join(', ')} and provides ${scene.outputs.join(', ')}. Entrances face the shared routes; nearby destinations influence placement.`;}
